CREATE TABLE IF NOT EXISTS administrators (id SERIAL PRIMARY KEY, username VARCHAR(60) NOT NULL UNIQUE, email VARCHAR(160) NOT NULL UNIQUE, password_hash TEXT NOT NULL, full_name VARCHAR(160) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS courses (id SERIAL PRIMARY KEY, course_code VARCHAR(20) NOT NULL UNIQUE, course_name VARCHAR(180) NOT NULL, department VARCHAR(180) NOT NULL, description TEXT, status VARCHAR(30) NOT NULL DEFAULT 'Active', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS students (id SERIAL PRIMARY KEY, student_id VARCHAR(30) NOT NULL UNIQUE, first_name VARCHAR(100) NOT NULL, middle_name VARCHAR(100), last_name VARCHAR(100) NOT NULL, email VARCHAR(160), contact_number VARCHAR(40), gender VARCHAR(30), course_id INTEGER REFERENCES courses(id) ON UPDATE CASCADE ON DELETE RESTRICT, year_level INTEGER NOT NULL CHECK(year_level BETWEEN 1 AND 6), year_block VARCHAR(20), department VARCHAR(180) NOT NULL, enrollment_status VARCHAR(30) NOT NULL DEFAULT 'Enrolled' CHECK(enrollment_status IN ('Enrolled','Not Enrolled','Graduated','Dropped')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS faculty (id SERIAL PRIMARY KEY, faculty_id VARCHAR(30) NOT NULL UNIQUE, first_name VARCHAR(100) NOT NULL, middle_name VARCHAR(100), last_name VARCHAR(100) NOT NULL, email VARCHAR(160) UNIQUE, contact_number VARCHAR(40), gender VARCHAR(30), department VARCHAR(180) NOT NULL, position VARCHAR(100) NOT NULL, employment_status VARCHAR(30) NOT NULL DEFAULT 'Active', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS enrollments (id SERIAL PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES students(id) ON UPDATE CASCADE ON DELETE RESTRICT, academic_year VARCHAR(20) NOT NULL, semester VARCHAR(30) NOT NULL, enrollment_status VARCHAR(30) NOT NULL CHECK(enrollment_status IN ('Enrolled','Not Enrolled','Graduated','Dropped')), enrollment_date DATE NOT NULL DEFAULT CURRENT_DATE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(student_id,academic_year,semester));
CREATE INDEX IF NOT EXISTS idx_students_name ON students(last_name,first_name); CREATE INDEX IF NOT EXISTS idx_students_course ON students(course_id); CREATE INDEX IF NOT EXISTS idx_students_status ON students(enrollment_status); CREATE INDEX IF NOT EXISTS idx_faculty_department ON faculty(department); CREATE INDEX IF NOT EXISTS idx_enrollments_student ON enrollments(student_id);

ALTER TABLE students ADD COLUMN IF NOT EXISTS year_block VARCHAR(20);
